const rows = $('Fetch Pending Claims').all().map(i => i.json).filter(r => r && r.claim_reference && String(r.status) === 'pending_review' && String(r.funder || '').toLowerCase() !== 'ndis');
const profiles = $('Fetch Funding Profiles').all().map(i => i.json).filter(p => p && p.patient_id);
const fees = $('Fetch Fee Schedule').all().map(i => i.json).filter(f => f && f.item_code);

const profByPatient = {};
for (const p of profiles) {
  if (String(p.active).toLowerCase() === 'yes') profByPatient[String(p.patient_id).trim()] = p;
}
const feeByCode = {};
for (const f of fees) feeByCode[String(f.item_code).trim().toUpperCase()] = f;

rows.sort((a, b) => String(a.participant_name || '').localeCompare(String(b.participant_name || '')) || String(a.service_date || '').localeCompare(String(b.service_date || '')));

const tally = {};
const claims = [];
for (const r of rows) {
  const pid = String(r.patient_id || '').trim();
  const prof = profByPatient[pid];
  const fee = feeByCode[String(r.support_item_number || '').trim().toUpperCase()];
  const approved = prof ? (Number(prof.sessions_approved) || 0) : 0;
  const usedBase = prof ? (Number(prof.sessions_used) || 0) : 0;
  const priorTally = tally[pid] || 0;
  const qty = Number(r.quantity) || 0;
  const remainingBefore = approved - usedBase - priorTally;
  const remainingAfter = remainingBefore - qty;
  tally[pid] = priorTally + qty;

  const warnings = [];
  if (!prof) warnings.push('No active funding profile found for this patient, so approve is disabled.');
  if (prof && !String(prof.insurer_email || '').trim()) warnings.push('Funding profile has no insurer email, so approve is disabled.');
  if (prof && !String(prof.claim_number || '').trim()) warnings.push('No insurer claim number on the funding profile.');
  const exp = prof ? String(prof.approval_expiry || '').slice(0, 10) : '';
  if (exp && String(r.service_date || '') > exp) warnings.push('Service date is after the approval expiry (' + exp + ').');
  if (prof && remainingAfter < 0) warnings.push('Not enough approved sessions remaining (' + Math.max(0, remainingBefore) + ' left under the current approval).');
  else if (prof && remainingAfter <= 2) warnings.push('Only ' + remainingAfter + ' approved session(s) will remain after this claim. An AHTR renewal is due.');
  if (String(r.validation_errors || '').trim()) warnings.push('Validation notes: ' + r.validation_errors);

  claims.push({
    claim_reference: r.claim_reference,
    invoice_number: r.invoice_number || '',
    participant_name: r.participant_name || 'Unknown',
    patient_id: pid,
    service_date: r.service_date || '',
    support_item_number: r.support_item_number || '',
    support_item_name: fee ? (fee.item_name || '') : '',
    quantity: qty,
    unit_price: Number(r.unit_price) || 0,
    total: Number(r.total) || 0,
    batch_id: r.batch_id || '',
    funder: r.funder || '',
    insurer_name: prof ? (prof.insurer_name || '') : '',
    insurer_email: prof ? (prof.insurer_email || '') : '',
    claim_number: prof ? (prof.claim_number || '') : '',
    approval_reference: prof ? (prof.approval_reference || '') : '',
    approval_expiry: exp,
    sessions_approved: approved,
    remaining_after: remainingAfter,
    can_approve: !!(prof && String(prof.insurer_email || '').trim()),
    warnings: warnings
  });
}

const payload = Buffer.from(JSON.stringify(claims), 'utf8').toString('base64');

