<body>
<div class="wrap">
<header class="hero">
  <div>
    <h1>🗂️ Claims Review</h1>
    <div class="sub">Final verification before invoices are emailed to insurers — nothing is sent until you approve it.</div>
  </div>
  <div class="hero-actions">
    <button id="refreshBtn" class="btn-ghost">↻ Refresh</button>
    <button id="approveAllBtn" class="btn-white">✓ Approve all sendable</button>
  </div>
</header>
<div class="stats">
  <div class="stat"><div class="ico ico-blue">📋</div><div><div class="num" id="statCount">0</div><div class="lbl">Awaiting review</div></div></div>
  <div class="stat"><div class="ico ico-gold">💵</div><div><div class="num" id="statTotal">$0.00</div><div class="lbl">Total value</div></div></div>
  <div class="stat"><div class="ico ico-green">✅</div><div><div class="num" id="statReady">0</div><div class="lbl">Ready to send</div></div></div>
</div>
