<script>
var claims = [];
try { claims = JSON.parse(decodeURIComponent(escape(atob(document.getElementById('__data').textContent.trim())))); } catch (e) { claims = []; }
function esc(v) { return String(v == null ? '' : v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;'); }
function money(n) { return '$' + (Number(n) || 0).toFixed(2); }
function field(label, value) { return '<div><div class="fl">' + esc(label) + '</div><div class="fv">' + esc(value) + '</div></div>'; }
function initials(name) {
  var p = String(name || '').trim().split(' ');
  var a = p[0] ? p[0].charAt(0) : '?';
  var b = p.length > 1 ? p[p.length - 1].charAt(0) : '';
  return (a + b).toUpperCase();
}
function post(payload) {
  var buttons = document.querySelectorAll('button');
  for (var i = 0; i < buttons.length; i++) buttons[i].disabled = true;
  fetch(window.location.href, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload) })
    .then(function (r) { if (!r.ok) throw new Error('HTTP ' + r.status); return r.text(); })
    .then(function () { window.location.reload(); })
    .catch(function (e) { alert('Action failed: ' + e + ' - reloading so you can try again.'); window.location.reload(); });
}
function render() {
  var sendable = 0; var totalValue = 0;
  for (var i = 0; i < claims.length; i++) { totalValue += Number(claims[i].total) || 0; if (claims[i].can_approve) sendable++; }
  document.getElementById('statCount').textContent = claims.length;
  document.getElementById('statTotal').textContent = money(totalValue);
  document.getElementById('statReady').textContent = sendable;
  document.getElementById('approveAllBtn').disabled = !sendable;
  var out = '';
  if (!claims.length) {
    out = '<div class="empty"><div class="big">🎉</div><h2>All clear — nothing to review</h2><p>New claims appear here after the nightly invoice run stages them for your approval.</p></div>';
  }
  for (var k = 0; k < claims.length; k++) {
    var c = claims[k];
    var badge = c.funder === 'ctp' ? '<span class="badge badge-ctp">CTP</span>' : (c.funder ? '<span class="badge badge-wc">' + esc(c.funder.split('_').join(' ')) + '</span>' : '<span class="badge badge-other">claim</span>');
    out += '<div class="card' + (c.can_approve ? '' : ' blocked') + '">';
    out += '<div class="card-head"><div class="avatar av' + (k % 3) + '">' + esc(initials(c.participant_name)) + '</div><div class="who"><div class="name-row"><span class="name">' + esc(c.participant_name) + '</span>' + badge + '</div><div class="ref">' + esc(c.claim_reference) + '</div></div><div class="amount">' + money(c.total) + '</div></div>';
    out += '<div class="sendto">' + (c.insurer_email ? '✉️ <span>Sends to <b>' + esc(c.insurer_email) + '</b>' + (c.insurer_name ? ' · ' + esc(c.insurer_name) : '') + '</span>' : '🚫 <span>No insurer email on file — this claim cannot be sent yet</span>') + '</div>';
    out += '<div class="grid">'
      + field('Insurer claim', c.claim_number || '—')
      + field('Approval', c.approval_reference || '—')
      + field('Invoice', c.invoice_number || '—')
      + field('Service date', c.service_date || '—')
      + field('Item', c.support_item_number + (c.support_item_name ? ' · ' + c.support_item_name : ''))
      + field('Qty × unit price', c.quantity + ' × ' + money(c.unit_price))
      + '</div>';
    if (c.can_approve && c.sessions_approved > 0) {
      var usedAfter = c.sessions_approved - c.remaining_after;
      var pct = Math.round((usedAfter / c.sessions_approved) * 100);
      if (pct < 0) pct = 0;
      if (pct > 100) pct = 100;
      var low = c.remaining_after <= 2;
      out += '<div class="sessions"><div class="fl">Approved sessions after send</div><div class="bar' + (low ? ' low' : '') + '"><i style="width:' + pct + '%"></i></div><div class="bar-lbl">' + usedAfter + ' of ' + c.sessions_approved + ' used · ' + c.remaining_after + ' left</div></div>';
    }
    for (var w = 0; w < c.warnings.length; w++) out += '<div class="warnbox">⚠️ <span>' + esc(c.warnings[w]) + '</span></div>';
    out += '<div class="actions">'
      + '<button class="btn-approve" data-act="approve" data-ref="' + esc(c.claim_reference) + '"' + (c.can_approve ? '' : ' disabled') + '>✓ Approve &amp; send</button>'
      + '<button class="btn-reject" data-act="reject" data-ref="' + esc(c.claim_reference) + '">✕ Reject</button>'
      + '</div>';
    out += '</div>';
  }
  document.getElementById('cards').innerHTML = out;
}
document.getElementById('cards').addEventListener('click', function (ev) {
  var t = ev.target;
  if (!t || !t.getAttribute) return;
  var act = t.getAttribute('data-act');
  var ref = t.getAttribute('data-ref');
  if (!act || !ref) return;
  var c = null;
  for (var i = 0; i < claims.length; i++) if (claims[i].claim_reference === ref) c = claims[i];
  var NL = String.fromCharCode(10);
  if (act === 'approve') {
    var msg = 'Approve and send this invoice now?';
    if (c) msg = 'Approve and send invoice ' + c.invoice_number + ' for ' + c.participant_name + ' (' + money(c.total) + ')' + NL + 'to ' + c.insurer_email + '?';
    if (confirm(msg)) post({ action: 'approve', claim_reference: ref });
  } else if (act === 'reject') {
    var reason = prompt('Reason for rejecting (saved to the claims ledger):', '');
    if (reason === null) return;
    post({ action: 'reject', claim_reference: ref, reason: reason });
  }
});
document.getElementById('approveAllBtn').addEventListener('click', function () {
  var n = 0; var v = 0;
  for (var i = 0; i < claims.length; i++) if (claims[i].can_approve) { n++; v += Number(claims[i].total) || 0; }
  if (!n) return;
  if (confirm('Approve and send ' + n + ' claim(s) totalling ' + money(v) + ' to their insurers?')) post({ action: 'approve_all' });
});
document.getElementById('refreshBtn').addEventListener('click', function () { window.location.reload(); });
render();
</script>
</body>
</html>`;

return [{ json: { html: html, pending_count: claims.length } }];

const wh = $('Claims Action').first().json;
const body = (wh && wh.body) ? wh.body : {};
const action = String(body.action || '').toLowerCase();
const targetRef = String(body.claim_reference || '').trim();
const reason = String(body.reason || '').trim();

const rows = $('Load Claims For Action').all().map(i => i.json).filter(r => r && r.claim_reference && String(r.status) === 'pending_review' && String(r.funder || '').toLowerCase() !== 'ndis');
const profiles = $('Load Profiles For Action').all().map(i => i.json).filter(p => p && p.patient_id);
const profByPatient = {};
for (const p of profiles) { if (String(p.active).toLowerCase() === 'yes') profByPatient[String(p.patient_id).trim()] = p; }

let targets = [];
if (action === 'approve_all') targets = rows;
else if (action === 'approve' || action === 'reject') targets = rows.filter(r => String(r.claim_reference) === targetRef);

if (!targets.length) return [{ json: { decision: 'none', message: 'No matching pending claim for action "' + action + '"' } }];

const out = [];
const tally = {};
for (const r of targets) {
  if (action === 'reject') {
    out.push({ json: { decision: 'reject', claim_reference: r.claim_reference, reason: reason || 'Rejected at final review' } });
    continue;
  }
  const pid = String(r.patient_id || '').trim();
  const prof = profByPatient[pid];
  const email = prof ? String(prof.insurer_email || '').trim() : '';
  if (!prof || !email) {
    if (action === 'approve') return [{ json: { decision: 'none', message: 'Claim has no active funding profile or insurer email, so it cannot be sent' } }];
    continue;
  }
  const approved = Number(prof.sessions_approved) || 0;
  const usedBase = Number(prof.sessions_used) || 0;
  const qty = Number(r.quantity) || 0;
  tally[pid] = (tally[pid] || 0) + qty;
  const usedNew = usedBase + tally[pid];
  const remainingAfter = approved - usedNew;

  const emailHtml = '<p>Please find below our tax invoice for approved treatment under claim <b>' + (prof.claim_number || '') + '</b>.</p>' +
    '<table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse">' +
    '<tr><th>Worker / claimant</th><td>' + (r.participant_name || '') + '</td></tr>' +
    '<tr><th>Insurer claim number</th><td>' + (prof.claim_number || '') + '</td></tr>' +
    '<tr><th>Treatment approval</th><td>' + (prof.approval_reference || '') + '</td></tr>' +
    '<tr><th>Invoice</th><td>' + (r.invoice_number || '') + '</td></tr>' +
    '<tr><th>Service</th><td>' + (r.support_item_number || '') + '</td></tr>' +
    '<tr><th>Service date</th><td>' + (r.service_date || '') + '</td></tr>' +
    '<tr><th>Quantity</th><td>' + qty + '</td></tr>' +
    '<tr><th>Amount</th><td>$' + (Number(r.total) || 0).toFixed(2) + '</td></tr></table>' +
    '<p>Please remit payment within your scheme terms, quoting the invoice number.</p>';

  out.push({ json: {
    decision: 'approve',
    claim_reference: r.claim_reference,
    patient_id: pid,
    participant_name: r.participant_name || '',
    invoice_number: r.invoice_number || '',
    claim_number: prof.claim_number || '',
    approval_reference: prof.approval_reference || '',
    insurer_email: email,
    insurer_name: prof.insurer_name || '',
    sessions_used_new: usedNew,
    remaining_after: remainingAfter,
    email_subject: 'Tax invoice ' + (r.invoice_number || '') + ' — claim ' + (prof.claim_number || '') + ' (' + (r.participant_name || '') + ')',
    email_html: emailHtml
  }});
}
if (!out.length) return [{ json: { decision: 'none', message: 'No sendable claims (missing insurer emails on funding profiles)' } }];
return out;

const claims = $('Apply Decision').all().map(i => i.json).filter(c => c.decision === 'approve' && Number(c.remaining_after) <= 2);
if (!claims.length) return [];
let rowsHtml = '';
for (const c of claims) {
  rowsHtml += '<tr><td>' + c.participant_name + '</td><td>' + c.claim_number + '</td><td>' + c.approval_reference + '</td><td>' + c.remaining_after + '</td></tr>';
}
const html = '<h2>AHTR renewals needed</h2>' +
  '<p>The following patients are nearly out of approved sessions. The practitioner should complete and submit a new Allied Health Treatment Request to the insurer before further treatment.</p>' +
  '<table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse">' +
  '<tr><th>Patient</th><th>Insurer claim</th><th>Current approval</th><th>Sessions left</th></tr>' + rowsHtml + '</table>';
return [{ json: { html: html, count: claims.length } }];
